mod game {
    pub struct Player {
        pub name: String,
        score: u32,
    }

    impl Player {
        pub fn new(name: &str) -> Player {
            Player { name: name.to_string(), score: 0 }
        }

        pub fn win(&mut self) {
            self.score += 10;
        }

        pub fn score(&self) -> u32 {
            self.score
        }
    }
}

fn main() {
    let mut p = game::Player::new("Rina");
    p.win();
    p.win();
    println!("{} {}", p.name, p.score());
}
